function formatTime(seconds){const tenths=Math.floor(Math.max(0,seconds)*10);return String(Math.floor(tenths/600)).padStart(2,'0')+':'+String(Math.floor(tenths/10)%60).padStart(2,'0')+'.'+tenths%10}
